function [tau] = couple_torques(thrust, arm)
%COUPLE_TORQUES  The six couples' body torques [N m] at full thrust: +-2 F arm about x, y and z in turn.
%   thrust: real[N] (passed in m kg/s^2)
%   arm: real[m][3] (passed in m)
%   returns tau: real[N m][3][ACT_NC] (passed in m^2 kg/s^2)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = zeros(6, 3);
    tau = zeros(6, 3);
    for ax = (0):((3) - 1)
        tau(((2 * ax)) + 1, (ax) + 1) = ((2 * thrust) * arm((ax) + 1));
        tau((((2 * ax) + 1)) + 1, (ax) + 1) = (((-(2)) * thrust) * arm((ax) + 1));
    end
end
